import inspect
import jwt

key = '0123456789abcdef0123456789abcdef'
token = jwt.encode({'sub': 'staticpython', 'admin': True}, key, algorithm='HS256')
decode_options = {}
if 'algorithms' in inspect.signature(jwt.decode).parameters:
    decode_options['algorithms'] = ['HS256']
payload = jwt.decode(token, key, **decode_options)
assert payload == {'sub': 'staticpython', 'admin': True}

